function exportMembers() {
  const rows = [['Member','Plan','Joined','Status','Pending dues'], ...Array.from(document.querySelectorAll('.member-row')).filter(r => r.style.display !== 'none').map(r => Array.from(r.querySelectorAll('td')).slice(0,5).map(td => td.innerText.replace(/\n/g,' ')))];
  const csv = rows.map(row => row.map(cell => `"${cell.replaceAll('"','""')}"`).join(',')).join('\n');
  const blob = new Blob([csv], {type:'text/csv'}); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = 'mission-gym-members.csv'; link.click(); URL.revokeObjectURL(link.href); showToast('Member report exported.');
}
function openMemberModal(){document.querySelector('#memberModal').classList.add('open');document.querySelector('#memberName')?.focus()}
function closeModals(){document.querySelectorAll('.modal-backdrop').forEach(modal=>modal.classList.remove('open'))}
function bindOverview(){const search=document.querySelector('#memberSearch');const statusFilter=document.querySelector('#statusFilter');const filterRows=()=>{const q=search?.value.toLowerCase()||'';const statusValue=statusFilter?.value||'';document.querySelectorAll('.member-row').forEach(row=>row.style.display=row.textContent.toLowerCase().includes(q)&&(!statusValue||row.dataset.status===statusValue)?'':'none')};if(search)search.oninput=filterRows;if(statusFilter)statusFilter.onchange=filterRows;document.querySelectorAll('.row-action').forEach(btn=>btn.onclick=()=>{const row=btn.closest('tr');document.querySelector('#detailName').textContent=row.querySelector('.member-name strong').textContent;document.querySelector('#detailPlan').textContent=row.children[1].textContent;document.querySelector('#detailModal').classList.add('open')})}
function bindModule(){const search=document.querySelector('#moduleSearch');const body=document.querySelector('#membersModuleBody');if(search&&body)search.oninput=()=>{const q=search.value.toLowerCase();body.querySelectorAll('tr').forEach(row=>row.style.display=row.textContent.toLowerCase().includes(q)?'':'none')};const renewalSearch=document.querySelector('#renewalSearch');if(renewalSearch)renewalSearch.oninput=()=>{const q=renewalSearch.value.toLowerCase();renewalSearch.closest('.panel').querySelectorAll('tbody tr').forEach(row=>row.style.display=row.textContent.toLowerCase().includes(q)?'':'none')};moduleHost.querySelectorAll('.switch').forEach(button=>button.onclick=()=>{button.classList.toggle('on');showToast(`Setting ${button.classList.contains('on')?'enabled':'disabled'}.`)})}
function handleAction(action){if(action==='Add member')return openMemberModal();if(['Download report','Export dues','Export attendance','Import members'].includes(action))return showToast(`${action} is ready to download.`);if(action==='Save settings')return showToast('Settings saved for this sample workspace.');if(['Send reminder','Send batch reminder','WhatsApp','Call','Schedule'].includes(action))return showToast(`${action} queued for follow-up.`);if(['Record payment','Collect','Collect payment'].includes(action))return showToast('Payment collection flow opened.');if(['Scan QR','Manual check-in'].includes(action))return showToast('Check-in desk is ready.');if(action==='Toggle setting')return;showToast(`${action} action selected.`)}
function selectModule(label){nav.forEach(item=>item.classList.toggle('active',item.dataset.label===label));document.querySelector('.admin-sidebar').classList.remove('open');if(label==='Overview'){heading.innerHTML=originalHeading;overviewNodes.forEach(node=>node.hidden=false);moduleHost.innerHTML='';document.querySelector('#exportBtn')?.addEventListener('click',exportMembers);document.querySelector('#addMemberBtn')?.addEventListener('click',openMemberModal);bindOverview();return}overviewNodes.forEach(node=>node.hidden=true);title.textContent=label.toUpperCase();desc.textContent=`${label} management — records, actions, and follow-ups in one place.`;moduleHost.innerHTML=templates[label]?templates[label]():`<article class="panel"><div class="module-empty"><strong>${label} module</strong>Connect this module to the gym CRM to manage live records.</div></article>`;bindModule()}
nav.forEach(item=>item.addEventListener('click',()=>{selectModule(item.dataset.label);showToast(`${item.dataset.label} module selected.`)}));
document.querySelector('.admin-mobile-toggle')?.addEventListener('click',()=>document.querySelector('.admin-sidebar').classList.toggle('open'));
document.querySelector('.admin-icon[data-notify]')?.addEventListener('click',()=>showToast('You have 3 renewal reminders to review.'));
document.querySelector('#exportBtn')?.addEventListener('click',exportMembers);document.querySelector('#addMemberBtn')?.addEventListener('click',openMemberModal);
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action)handleAction(action);if(e.target.closest('[data-close-modal]'))closeModals()});document.querySelectorAll('.modal-backdrop').forEach(backdrop=>backdrop.addEventListener('click',e=>{if(e.target===backdrop)closeModals()}));
document.querySelector('#memberForm')?.addEventListener('submit',e=>{e.preventDefault();const name=document.querySelector('#memberName').value;const plan=document.querySelector('#memberPlan').value;const initials=name.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase();const overview=document.querySelector('#memberTableBody');const moduleBody=document.querySelector('#membersModuleBody');const rowHtml=`<tr class="member-row module-member-row" data-status="active"><td><div class="member-name"><span class="avatar">${initials}</span><div><strong>${name}</strong><span>TMG-${Math.floor(1000+Math.random()*9000)}</span></div></div></td><td>${plan}</td><td>16 Oct 2026</td><td>${status('Active','active')}</td><td>₹0</td><td><button class="row-action">⋯</button></td></tr>`;if(overview)overview.insertAdjacentHTML('afterbegin',rowHtml);if(moduleBody)moduleBody.insertAdjacentHTML('afterbegin',rowHtml);closeModals();e.target.reset();showToast(`${name} added to members.`)});
bindOverview();
